Here's a Python script that computes the **1,000,000th Fibonacci number exactly** and writes it (or the full sequence) to a file:

```python
def fib(n):
    """Return the nth Fibonacci number using fast doubling (exact integer)."""
    def fib_pair(k):
        if k == 0:
            return (0, 1)
        else:
            a, b = fib_pair(k >> 1)
            c = a * ((b << 1) - a)
            d = a * a + b * b
            if k & 1:
                return (d, c + d)
            else:
                return (c, d)
    return fib_pair(n)[0]

n = 1_000_000
result = fib(n)

# Write the millionth term to a file
with open("fib_1e6.txt", "w") as f:
    f.write(str(result))

print(f"F({n}) has {len(str(result))} digits and was written to fib_1e6.txt")
