 *  Ok, this is the main fork-routine.
 *
 * It copies the process, and if no error, wakes it up and waits for
 * it to finish using the VM.
 *
 * It also copies the registers, and the necessary parts of the process
 * context.
 */
long do_fork(unsigned long clone_flags,
	      unsigned long stack_start,
	      unsigned long stack_size,
	      int __user *parent_tidptr,
	      int __user *child_tidptr)
{
	struct task_struct *p;
	int trace = 0;
	long nr;

	/*
	 * Determine whether we'll be tracing the child, and whether
	 * we'll need to force the child to use a specific signal
	 * upon termination.
	 */
	if (!(clone_flags & CLONE_UNTRACED)) {
		if (clone_flags & CLONE_VFORK)
			trace = PTRACE_EVENT_VFORK;
		else if ((clone_flags & CSIGNAL) != SIGCHLD)
			trace = PTRACE_EVENT_CLONE;
		else
			trace = PTRACE_EVENT_FORK;

		if (likely(!ptrace_event_enabled(current, trace)))
			trace = 0;
	}

	p = copy_process(clone_flags, stack_start, stack_size,
			 child_tidptr, NULL, trace, NUMA_NO_NODE);
	/*
	 * Do the subsystems ready for the new process setup.
	 */
	if (!IS_ERR(p)) {
		struct pid *pid;
		struct completion vfork;
		struct kernel_siginfo info;

		/*
		 * Ensure that the child's cached domain info is
		 * valid, since the parent's domain info might have
		 * changed after the copy_process() call.
		 */
		security_task_post_create(p);

		pid = get_task_pid(p, PIDTYPE_PID);
		nr = pid_vnr(pid);

		if (clone_flags & CLONE_PARENT_SETTID)
			put_user(nr, parent_tidptr);

		if (clone_flags & CLONE_VFORK) {
			p->vfork_done = &vfork;
			init_completion(&vfork);
			get_task_struct(p);
		}

		wake_up_new_task(p);

		/* forking complete and child started to run, tell ptracer */
		if (unlikely(trace))
			ptrace_event_pid(trace, pid);

		if (clone_flags & CLONE_VFORK) {
			if (!wait_for_vfork_done(p, &vfork))
				ptrace_event_pid(PTRACE_EVENT_VFORK_DONE, pid);
		}

		put_pid(pid);
	} else {
		nr = PTR_ERR(p);
	}
	return nr;
}
```

**Note:** In newer kernel versions (roughly 5.0+), `do_fork` was often renamed or refactored into `_do_fork` and subsequently `kernel_clone` to handle kernel thread creation, with `do_fork` sometimes becoming a wrapper or removed entirely in favor of specific syscall handlers.

