 *
 *  This is the core function for creating new processes.  It performs
 *  the following steps:
 *
 *  1. Check for errors and limitations.
 *  2. Duplicate the process's credentials.
 *  3. Allocate a process structure (task_struct).
 *  4. Duplicate the process's memory space.
 *  5. Duplicate the process's file descriptor table.
 *  6. Duplicate the process's signal handlers.
 *  7. Initialize the new process's kernel stack.
 *  8. Schedule the new process.
 */

long do_fork(unsigned long clone_flags, unsigned long stack_ptr)
{
	struct task_struct *p;
	int ret = -ENOMEM;

	/*
	 *  Duplicate the current process.
	 */
	p = dup_task_struct(current);
	if (!p)
		goto out;

	/*
	 *  Copy the credentials.
	 */
	copy_creds(p, current);

	/*
	 *  Initialize the process structure.
	 */
	p->stack = stack_ptr;
#ifdef CONFIG_NUMA_BALANCING
	p->numa_preferred_node = current->numa_preferred_node;
#endif
	p->flags &= ~(PF_STARTABLE | PF_EXITING);
	p->pid = last_pid++;
	p->comm = get_task_comm(current);
	p->delay_count = 0;
	p->blocked = 0;
	p->lock_depth = 0;

	/*
	 *  Duplicate the process's memory space.
	 */
	ret = dup_mm(current, p);
	if (ret != 0)
		goto bad_fork_cleanup;

	/*
	 *  Duplicate the process's file descriptor table.
	 */
	ret = dup_fd_table(current, p);
	if (ret != 0) {
		goto bad_fork_cleanup_mm;
	}

	/*
	 *  Duplicate the process's signal handlers.
	 */
	ret = dup_signal_map(current, p);
	if (ret != 0) {
		goto bad_fork_cleanup_fdtable;
	}

	/*
	 *  Initialize the new process's kernel stack.
	 */
	setup_thread_stack(p, stack_ptr);

#ifdef CONFIG_DEBUG_VM
	/* Ensure the initial memory mappings are valid */
	if (unlikely(check_stack(p)))
		goto bad_fork_cleanup_sig;
#endif

	/*
	 *  Set up the new process's accounting information.
	 */
	acct_init(p);

	/*
	 *  Schedule the new process.
	 */
	if (clone_flags & CLONE_PARENT) {
		/*
		 *  CLONE_PARENT: The child will share the parent's PID namespace.
		 */
		p->pid = current->pid;
	} else {
		/*
		 *  CLONE_CHILD: The child will have a unique PID.
		 */
		p->pid = last_pid++;
	}

	/*
	 *  Wake up the new process.
	 */
	p->need_resched = 1;

	/*
	 *  Mark the process as running.
	 */
	set_task_state(p, TASK_RUNNING);

	/*
	 *  Add the process to the scheduler's run queue.
	 */
	schedule();

	/*
	 *  This code should never be reached.
	 */
	ret = -EPERM;

bad_fork_cleanup_sig:
	clear_signal_map(p);
bad_fork_cleanup_fdtable:
	free_fdtable(p);
bad_fork_cleanup_mm:
	free_mm(p);
bad_fork_cleanup:
	free_task_struct(p);

out:
	return ret;
}
