/*
 * This is the main workhorse for fork(2), vfork(2), and clone(2) system calls.
 * It performs the following:
 *
 * 1.  Duplicate the process's data structures:
 *     - task_struct (process descriptor)
 *     - mm_struct (memory management information)
 *     - signal handlers and blocked signals
 *     - file descriptor table
 *
 * 2.  Create a new process ID (PID).
 *
 * 3.  Set up the new process's context:
 *     - stack pointer
 *     - instruction pointer
 *     - registers
 *
 * 4.  Wake up the new process.
 */

static int copy_process(unsigned long clone_flags, pid_t *ptid,
			struct pid_namespace *pidns,
			struct task_struct *tpl,
			struct task_struct *tk)
{
	int retval = 0;
	struct files_struct *files = tpl->files;
	struct fs_struct *fs = tpl->fs;

	/* Copy the mm_struct */
	if (clone_flags & CLONE_VM) {
		tk->mm = tpl->mm;
		tk->active_mm = tpl->active_mm;
		atomic_inc(&tpl->mm->mm_count);
		tk->dumpable = tpl->dumpable;
	} else {
		tk->mm = dup_mm(tpl->mm);
		if (!tk->mm)
			return -ENOMEM;
		tk->active_mm = tk->mm;
	}

	/* Copy the signal handlers and blocked signals */
	tk->signal = vfork_copy_signal(tpl);
	if (!tk->signal)
		return -ENOMEM;
	tk->sighand = tpl->sighand;

	/* Copy the file descriptor table */
	tk->files = files;
	files_inc(files);

	/* Copy the fs_struct */
	tk->fs = fs;
	fs_inc(fs);

	/* Copy the process's PID */
	tk->pid = pidns_pid_next(pidns);
	if (tk->pid < 0) {
		retval = tk->pid;
		goto cleanup_fs;
	}

	/* Copy the cgroup information */
	cgroup_clone_task(tk, tpl);

	/* Copy the timer signal */
	tk->timer_signal = tpl->timer_signal;

	/* Copy the nice value and scheduling policy */
	tk->nice = tpl->nice;
	tk->policy = tpl->policy;

	/* Copy the CPU affinity mask */
	tk->cpus_allowed = tpl->cpus_allowed;

	/* Copy the NUMA policy */
#ifdef CONFIG_NUMA_BALANCING
	tk->numa_preferred_node = tpl->numa_preferred_node;
#endif

	/* Copy the keyring information */
#ifdef CONFIG_KEYS
	keyrings_clone(tk, tpl);
#endif

	/* Copy the task's flags */
	tk->flags = tpl->flags;

	/* Copy the stack size */
	tk->stack_size = tpl->stack_size;

	/* Copy task_struct fields that are not duplicated above */
	*tk = *tpl;

	if (ptid)
		*ptid = tk->pid;

cleanup_fs:
	return retval;
}


/*
 *  Do a fork.  This function is called from kernel threads,
 *  and so cannot rely on having a current process context.
 */
pid_t do_fork(unsigned long clone_flags, unsigned long stack_start,
	      struct pid_namespace *pidns, int __user *child_ptid,
	      int trace, unsigned long audit_info)
{
	struct task_struct *p;
	pid_t pid;
	int retval;

	/* Check for clone flags that need special handling */
	if (clone_flags & CLONE_PARENT_SETTID) {
		if (put_user(0, child_ptid))
			return -EFAULT;
	} else if (clone_flags & CLONE_CHILD_SETTID) {
		/*
		 * This isn't fully implemented yet, and is prone to race conditions.
		 * It's more trouble than it's worth.
		 */
		printk(KERN_WARNING "CLONE_CHILD_SETTID is not fully supported\n");
	}

	/* Allocate the new task structure */
	p = dup_task_struct(current);
	if (!p)
		return -ENOMEM;

	/* Zero out the part of the new task structure that we didn't copy. */
	memset(&p->comm, 0, sizeof(p->comm));

	/* Copy the process information */
	retval = copy_process(clone_flags, &pid, pidns, current, p);
	if (retval) {
		/* free the partially created task structure */
		put_task_struct(p);
		return retval;
	}

	pid = p->pid;

	/* Trace me flags */
	if (trace) {
		p->ptrace = 1;
		/*
		 * If the tracing process wants to be notified when the child
		 * is stopped or otherwise changes state, we need to set
		 * PTRACE_STOP to ensure we send the signal.
		 */
		p->flags |= PF_PTRACED;
	}

	/* Initialize the new process's stack */
	p->stack = stack_start;
	p->stack_size = get_stack_size();

#ifdef CONFIG_SMP
	get_cpu_var(p->cpus_allowed) = current->cpus_allowed;
#endif

	/* Call the scheduler */
	sched_fork(current, p);

	return pid;
}
