	CLONE_NEWIPC		= 0x00004000,	/* Create new IPC namespace */
	CLONE_NEWPID		= 0x00008000,	/* Create new PID namespace */
	CLONE_NEWUTS		= 0x00010000,	/* Create new UTS namespace */
	CLONE_NEWNET		= 0x00020000,	/* Create new network namespace */
	CLONE_PARENT		= 0x00040000,	/* Inherit parent's cpuset */
	CLONE_CHILD		= 0x00080000,	/* Child sees parent's cpuset */
	CLONE_NOTIFY_REPARENT	= 0x00100000,	/* Notify parent when reparented */
